// launcher settings seeding selftest — the permission-preset seed and its
// launcher-owned marker (S1 step 3, docs/plans/arxa-isolation-levels.md).
// Run: node bin/selftest.launcher-settings.mjs
//
// The rules the brief fixes, pinned here:
//   * a NEW profile is seeded permission.defaultPreset=workspace-write;
//   * an EXISTING profile migrates ONLY when the marker proves the old value
//     was generated by this launcher (marker value == current value);
//   * an indistinguishable operator value stays untouched and gets a visible
//     remediation notice — arxa never silently overwrites a human choice.

import { strict as assert } from 'node:assert'
import { spawnSync } from 'node:child_process'
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { markerFor, seedPermissionPreset } from './seed-settings.mjs'

const here = dirname(fileURLToPath(import.meta.url))
let checks = 0
let skipped = 0
const ok = (name) => { checks += 1; console.log('  ok', name) }
const skip = (name, why) => { skipped += 1; console.log('  SKIP', name, '—', why) }

// ---- 1. pure rules ----------------------------------------------------------
{
  const W = 'workspace-write'

  // No marker: an operator (or a pre-marker arxa) value is indistinguishable
  // from a deliberate choice — kept, with the visible remediation notice.
  const operator = 'llm-pi-ai:\n  providers: {}\npermission:\n  defaultPreset: danger-full-access\n'
  const r1 = seedPermissionPreset(operator, { preset: W })
  assert.equal(r1.action, 'kept')
  assert.equal(r1.text, operator, 'not one byte moves')
  assert.ok(r1.notice.includes('danger-full-access') && r1.notice.includes(W),
    'the notice names the current value and the recommendation')
  ok('pure: unmarked operator value kept byte-for-byte + remediation notice')

  // Marker proving the CURRENT value was generated here → migrate.
  const marked = `permission:\n  ${markerFor('danger-full-access')}\n  defaultPreset: danger-full-access\n`
  const r2 = seedPermissionPreset(marked, { preset: W })
  assert.equal(r2.action, 'migrated')
  assert.ok(r2.text.includes(`  defaultPreset: ${W}`), 'the value is rewritten')
  assert.ok(r2.text.includes(markerFor(W)), 'the marker moves with it')
  assert.ok(r2.notice !== undefined && r2.notice.length > 0, 'the migration is announced')
  ok('pure: marker-proven generated value migrates to the preset, marker updated')

  // Marker present but the value has since been edited by the operator →
  // the operator's edit outranks the marker; keep + notice.
  const edited = `permission:\n  ${markerFor(W)}\n  defaultPreset: read-only\n`
  const r3 = seedPermissionPreset(edited, { preset: W })
  assert.equal(r3.action, 'kept')
  assert.equal(r3.text, edited)
  assert.ok(r3.notice.includes('read-only'))
  ok('pure: an operator edit after the marker wins — kept + notice')

  // Already at the target, unmarked: an operator who independently chose the
  // same value is NOT retroactively claimed as generated (no marker added).
  const same = 'permission:\n  defaultPreset: workspace-write\n'
  const r4 = seedPermissionPreset(same, { preset: W })
  assert.equal(r4.action, 'kept')
  assert.equal(r4.text, same, 'no marker is injected into an operator file')
  ok('pure: operator-set-to-target stays unclaimed (no marker injection)')

  // No permission block at all — nothing to migrate, but still noticed.
  const none = 'llm-pi-ai:\n  providers: {}\n'
  const r5 = seedPermissionPreset(none, { preset: W })
  assert.equal(r5.action, 'kept')
  assert.equal(r5.text, none)
  assert.ok(r5.notice.includes(W))
  ok('pure: a file with no permission block is kept + noticed')

  // Idempotence of the marker function itself.
  assert.equal(markerFor(W), markerFor(W))
  ok('pure: the marker is deterministic')
}

// ---- 2. end-to-end through the real launcher (--materialise-only) ----------
// Boots the actual bin/arxa-studio.mjs against a scratch ARXA_HOME — the same
// path every install takes, not a reimplementation. Needs the repo checkout
// (no pnpm, no network: materialise-only exits before the install step).
{
  const hasDeps = existsSync(join(here, '..', 'node_modules', '@deepseek-ai', 'dsh'))
  if (!hasDeps) {
    skip('e2e: materialise-only seeds workspace-write', 'node_modules not installed')
  } else {
    const home = mkdtempSync(join(tmpdir(), 'arxa-launcher-seed-'))
    try {
      const run = (env = {}) => spawnSync(process.execPath, [join(here, 'arxa-studio.mjs'), '--materialise-only'], {
        encoding: 'utf8',
        timeout: 60_000,
        env: { ...process.env, ARXA_HOME: home, ...env }
      })
      const settings = () => readFileSync(join(home, 'dsh', 'settings.yaml'), 'utf8')

      // Fresh home: seeded workspace-write WITH the marker.
      const r1 = run()
      assert.equal(r1.status, 0, 'materialise-only exits 0: ' + (r1.stderr || '').slice(0, 300))
      assert.ok(settings().includes('defaultPreset: workspace-write'), 'new profiles get workspace-write')
      assert.ok(settings().includes(markerFor('workspace-write')), 'the seed carries the launcher-owned marker')
      ok('e2e: fresh home seeds workspace-write + marker')

      // Second run: idempotent — byte-identical file, no rewrite noise.
      const before = settings()
      const r2 = run()
      assert.equal(r2.status, 0)
      assert.equal(settings(), before, 'an already-seeded file is not rewritten')
      assert.ok(!r2.stdout.includes('migrat'), 'no migration notice on a no-op run')
      ok('e2e: re-materialise is a byte-identical no-op')

      // Marker-proven old value (simulate a future preset change by planting
      // a marker that matches the on-disk value, target differs): migrates.
      writeFileSync(join(home, 'dsh', 'settings.yaml'),
        settings().replace('defaultPreset: workspace-write', 'defaultPreset: danger-full-access')
          .replace(markerFor('workspace-write'), markerFor('danger-full-access')))
      const r3 = run()
      assert.equal(r3.status, 0)
      assert.ok(settings().includes('defaultPreset: workspace-write'), 'the marker-proven value healed')
      assert.ok(r3.stdout.includes('danger-full-access'), 'the migration is announced on stdout')
      ok('e2e: marker-proven value migrates back with a visible notice')

      // Operator value with NO marker: untouched, remediation notice visible.
      writeFileSync(join(home, 'dsh', 'settings.yaml'),
        'permission:\n  defaultPreset: danger-full-access\n')
      const r4 = run()
      assert.equal(r4.status, 0)
      assert.ok(readFileSync(join(home, 'dsh', 'settings.yaml'), 'utf8')
        .includes('defaultPreset: danger-full-access'), 'the operator value survives untouched')
      assert.ok(r4.stdout.toLowerCase().includes('recommend') || r4.stdout.includes('workspace-write'),
        'a visible remediation notice points at the recommendation')
      ok('e2e: indistinguishable operator value kept + remediation notice')
    } finally {
      rmSync(home, { recursive: true, force: true })
    }
  }
}

console.log(`launcher-settings selftest: ${checks} checks green` + (skipped > 0 ? `, ${skipped} skipped` : ''))
